"""Offline side-by-side gallery, real captures and approved prototype only."""
import base64,json,sys
from pathlib import Path
folder=Path(sys.argv[1]); ids=sys.argv[2:]
images={p.name:'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode() for p in folder.glob('*.png')}
html='''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashfort · Comparación</title><style>body{font:16px/1.5 system-ui;margin:24px;background:#eef1f4;color:#182535}select{font:inherit;padding:8px;margin:8px}#wrap{overflow:auto}#grid{display:flex;gap:24px;width:max-content}figure{margin:0}figcaption{padding:8px}img{display:block;max-width:100%;box-shadow:0 0 0 1px #ccd3da}p{max-width:950px}</style><h1>Dashfort Mobile · comparación del lote</h1><p>Izquierda: prototipo aprobado en su tamaño original. Derecha: componentes React Native reales en Chromium sin red. La propuesta B se aplica solo a los controles autorizados; las fechas, datos y estados son ficticios y funcionales. Esto no acredita pruebas Android/iOS.</p><label>Pantalla<select id="screen">OPTIONS</select></label><label>Tema<select id="theme"><option value="light">Claro</option><option value="dark">Oscuro</option></select></label><label>Tamaño<select id="size"><option>390x844</option><option>360x640</option></select></label><div id="wrap"><div id="grid"></div></div><script>const images=IMAGES;function render(){const id=screen.value,t=theme.value,s=size.value;grid.innerHTML=[['Maqueta aprobada',`reference-${id}-${t}.png`,390],['Implementación real',`${id}-${t}-${s}.png`,Number(s.split('x')[0])]].map(([title,key,w])=>`<figure style="width:${w}px"><figcaption>${title}</figcaption><img alt="${title}" src="${images[key]}"></figure>`).join('')}const screen=document.getElementById('screen'),theme=document.getElementById('theme'),size=document.getElementById('size'),grid=document.getElementById('grid');document.querySelectorAll('select').forEach(x=>x.onchange=render);render();</script></html>'''
html=html.replace('OPTIONS',''.join(f'<option>{i}</option>' for i in ids)).replace('IMAGES',json.dumps(images))
(folder/'comparacion.html').write_text(html)
print(json.dumps({'gallery':str(folder/'comparacion.html'),'images':len(images)}))
